<?php require_once __DIR__.'/../app/bootstrap.php';require_admin();$active='courses';$pageTitle='NSDA কোর্স ব্যবস্থাপনা';$error='';$flash=$_SESSION['flash']??'';unset($_SESSION['flash']);$editing=null;
$images=['assets/campus-1.webp','assets/campus-2.webp','assets/campus-3.webp','assets/campus-4.webp','assets/campus-5.jpg'];$icons=['fa-desktop','fa-pen-nib','fa-laptop-code','fa-bolt','fa-drafting-compass','fa-microchip','fa-wrench','fa-code','fa-book-open','fa-graduation-cap'];
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$id=(int)($_POST['id']??0);if(isset($_POST['delete'])){$st=$pdo->prepare('DELETE FROM courses WHERE id=?');$st->execute([$id]);$_SESSION['flash']='কোর্স মুছে ফেলা হয়েছে।';header('Location: courses.php');exit;}if(isset($_POST['toggle'])){$pdo->prepare("UPDATE courses SET status=IF(status='active','hidden','active') WHERE id=?")->execute([$id]);$_SESSION['flash']='কোর্সের প্রকাশের অবস্থা পরিবর্তন হয়েছে।';header('Location: courses.php');exit;}
$title=trim($_POST['title']??'');$level=trim($_POST['level_label']??'');$category=trim($_POST['category']??'NSDA Skill Course');$summary=trim($_POST['summary']??'');$icon=$_POST['icon']??'fa-graduation-cap';$image=trim((string)($_POST['existing_image']??($editing['image_path']??($_POST['image_path']??'assets/campus-5.jpg'))));if(!empty($_FILES['course_image']['name'])){$f=$_FILES['course_image'];if(($f['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_OK){$error='ছবি আপলোড করা যায়নি।';}elseif(($f['size']??0)>5*1024*1024){$error='ছবির সর্বোচ্চ সাইজ ৫ MB।';}else{$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??'';if($ext===''||!@getimagesize($f['tmp_name']))$error='শুধু JPG, PNG অথবা WEBP ছবি আপলোড করুন।';else{$dir=__DIR__.'/../uploads/site';if(!is_dir($dir))@mkdir($dir,0755,true);$fn='course-'.date('YmdHis').'-'.bin2hex(random_bytes(4)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$fn))$error='ছবি সংরক্ষণ করা যায়নি।';else$image='live/uploads/site/'.$fn;}}}$duration=trim($_POST['duration_label']??'');$status=($_POST['status']??'active')==='hidden'?'hidden':'active';$sort=(int)($_POST['sort_order']??0);
if($error){}elseif(mb_strlen($title)<2)$error='কোর্সের নাম লিখুন।';elseif(mb_strlen($summary)<5)$error='কোর্সের সংক্ষিপ্ত বিবরণ লিখুন।';elseif(!preg_match('#^(assets/campus-[1-5]\.(webp|jpg)|live/uploads/site/[a-zA-Z0-9._-]+)$#',$image))$error='ছবির নির্বাচন সঠিক নয়।';elseif(!in_array($icon,$icons,true))$error='আইকন নির্বাচন সঠিক নয়.';else{if($id){$st=$pdo->prepare('UPDATE courses SET title=?,level_label=?,category=?,summary=?,icon=?,image_path=?,duration_label=?,status=?,sort_order=? WHERE id=?');$st->execute([$title,$level,$category,$summary,$icon,$image,$duration,$status,$sort,$id]);$_SESSION['flash']='কোর্সের তথ্য আপডেট হয়েছে.';}else{$st=$pdo->prepare('INSERT INTO courses(title,level_label,category,summary,icon,image_path,duration_label,status,sort_order) VALUES(?,?,?,?,?,?,?,?,?)');$st->execute([$title,$level,$category,$summary,$icon,$image,$duration,$status,$sort]);$_SESSION['flash']='নতুন কোর্স যোগ হয়েছে.';}try{$lg=$pdo->prepare('INSERT INTO activity_logs(admin_id,action,details,ip_address) VALUES(?,?,?,?)');$lg->execute([$_SESSION['admin_id'],'course_saved',$title,$_SERVER['REMOTE_ADDR']??'']);}catch(Throwable $e){}header('Location: courses.php');exit;}}
if(isset($_GET['edit'])){$st=$pdo->prepare('SELECT * FROM courses WHERE id=?');$st->execute([(int)$_GET['edit']]);$editing=$st->fetch()?:null;} $rows=$pdo->query('SELECT * FROM courses ORDER BY sort_order,id')->fetchAll();require __DIR__.'/_head.php';?>
<?php if($flash):?><div class="alert alert-success"><?=e($flash)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?>
<div class="panel mb-4" id="courseForm"><div class="section-label mb-1"><?=$editing?'কোর্স সম্পাদনা':'নতুন NSDA কোর্স যোগ করুন'?></div><div class="hint mb-3">কোর্সের তথ্য সংরক্ষণ করলে পাবলিক ওয়েবসাইটে স্বয়ংক্রিয়ভাবে আপডেট হবে।</div><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)($editing['id']??0)?>"><input type="hidden" name="existing_image" value="<?=e($editing['image_path']??'assets/campus-5.jpg')?>"><div class="row g-3"><div class="col-12 col-md-6"><label class="form-label">কোর্সের নাম *</label><input class="form-control" name="title" required maxlength="220" value="<?=e($editing['title']??'')?>"></div><div class="col-12 col-md-3"><label class="form-label">লেভেল / ব্যাচ</label><input class="form-control" name="level_label" maxlength="100" value="<?=e($editing['level_label']??'')?>" placeholder="যেমন: লেভেল ৩"></div><div class="col-12 col-md-3"><label class="form-label">ক্যাটাগরি</label><input class="form-control" name="category" maxlength="100" value="<?=e($editing['category']??'NSDA Skill Course')?>"></div><div class="col-12"><label class="form-label">সংক্ষিপ্ত বিবরণ *</label><textarea class="form-control" name="summary" required rows="3" maxlength="2000"><?=e($editing['summary']??'')?></textarea></div><div class="col-12 col-md-6"><label class="form-label">কোর্সের ছবি আপলোড (JPG/PNG/WEBP, সর্বোচ্চ ৫ MB)</label><input class="form-control" type="file" name="course_image" accept="image/jpeg,image/png,image/webp"><div class="hint">নতুন ছবি না দিলে বর্তমান ছবি অপরিবর্তিত থাকবে।</div><?php if(!empty($editing['image_path'])):?><img src="../../<?=e($editing['image_path'])?>" alt="" style="margin-top:8px;width:160px;height:95px;object-fit:cover;border-radius:10px"><?php endif;?></div><div class="col-12 col-md-4"><label class="form-label">আইকন</label><select class="form-select" name="icon"><?php foreach($icons as $ic):?><option value="<?=e($ic)?>" <?=($editing['icon']??'fa-graduation-cap')===$ic?'selected':''?>><?=e($ic)?></option><?php endforeach;?></select></div><div class="col-12 col-md-4"><label class="form-label">সময়সূচির বিবরণ</label><input class="form-control" name="duration_label" maxlength="120" value="<?=e($editing['duration_label']??'')?>" placeholder="প্রশিক্ষণ ব্যাচ অনুযায়ী"></div><div class="col-6 col-md-3"><label class="form-label">ক্রম</label><input class="form-control" type="number" name="sort_order" value="<?=e($editing['sort_order']??((count($rows)+1)*10))?>"></div><div class="col-6 col-md-3"><label class="form-label">প্রকাশের অবস্থা</label><select class="form-select" name="status"><option value="active" <?=($editing['status']??'active')==='active'?'selected':''?>>চলমান / প্রকাশিত</option><option value="hidden" <?=($editing['status']??'')==='hidden'?'selected':''?>>আড়াল করা</option></select></div><div class="col-12 d-flex gap-2 flex-wrap"><button class="btn btn-primary" type="submit"><i class="fa-solid fa-floppy-disk me-1"></i> <?=$editing?'পরিবর্তন সংরক্ষণ':'কোর্স যোগ করুন'?></button><?php if($editing):?><a class="btn btn-outline-secondary" href="courses.php">বাতিল</a><?php endif;?></div></div></form></div>
<div class="panel"><div class="d-flex justify-content-between align-items-center gap-2 mb-3"><div><div class="section-label">সকল কোর্স</div><div class="hint">চলমান কোর্স ওয়েবসাইটে দেখা যাবে; আড়াল করা কোর্স শুধু ড্যাশবোর্ডে থাকবে।</div></div><span class="badge-status bg-light text-dark"><?=count($rows)?>টি</span></div><div class="table-wrap"><table class="table"><thead><tr><th>কোর্স</th><th>লেভেল</th><th>ক্রম</th><th>অবস্থা</th><th>কাজ</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><div class="notice-title"><?=e($r['title'])?></div><div class="hint"><?=e(mb_strimwidth($r['summary'],0,100,'…','UTF-8'))?></div></td><td><?=e($r['level_label'])?></td><td><?= (int)$r['sort_order']?></td><td><span class="badge-status <?=$r['status']==='active'?'bg-success-subtle text-success':'bg-secondary-subtle text-secondary'?>"><?=$r['status']==='active'?'চলমান':'আড়াল করা'?></span></td><td><div class="d-flex gap-1 flex-wrap"><a class="btn btn-sm btn-outline-primary" href="?edit=<?=(int)$r['id']?>#courseForm">সম্পাদনা</a><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-outline-secondary" name="toggle" value="1"><?=$r['status']==='active'?'আড়াল':'প্রকাশ'?></button></form><form method="post" onsubmit="return confirm('এই কোর্স মুছে ফেলবেন?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-outline-danger" name="delete" value="1">মুছুন</button></form></div></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/_foot.php';?>
